import java.util.*;

class Solution {
    public int highestAverage(String[][] scores) {
        if (scores == null || scores.length == 0) return 0;
        Map<String, long[]> agg = new HashMap<>();          // name -> {sum, count}
        for (String[] rec : scores) {
            long[] sc = agg.computeIfAbsent(rec[0], k -> new long[2]);
            sc[0] += Integer.parseInt(rec[1].trim());
            sc[1]++;
        }
        double best = Double.NEGATIVE_INFINITY;
        for (long[] sc : agg.values()) best = Math.max(best, (double) sc[0] / sc[1]);
        return (int) Math.floor(best);
    }
}

class Solution {
    public int numDecodings(String s) {
        int prev2 = 1;                                   // dp[i-2], empty prefix
        int prev1 = s.charAt(0) == '0' ? 0 : 1;          // dp[i-1]
        for (int i = 2; i <= s.length(); i++) {
            int cur = 0;
            char one = s.charAt(i - 1);
            int two = (s.charAt(i - 2) - '0') * 10 + (one - '0');
            if (one != '0') cur += prev1;                // decode single digit
            if (two >= 10 && two <= 26) cur += prev2;    // decode pair
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
}

class Solution {
    public double myPow(double x, int n) {
        long N = n;                    // avoid overflow on -Integer.MIN_VALUE
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        double result = 1;
        while (N > 0) {
            if ((N & 1) == 1) result *= x;  // current bit set
            x *= x;                          // square for next bit
            N >>= 1;
        }
        return result;
    }
}

class Solution {
    public int countPrimes(int n) {
        if (n < 3) return 0;
        boolean[] composite = new boolean[n];
        int count = 0;
        for (int i = 2; i < n; i++) {
            if (composite[i]) continue;
            count++;
            if ((long) i * i < n) {
                for (int j = i * i; j < n; j += i) composite[j] = true;
            }
        }
        return count;
    }
}

import java.util.*;

class LRUCache {
    private static final class Node {
        int key, val;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }
    private final int capacity;
    private final Map<Integer, Node> map = new HashMap<>();
    private final Node head = new Node(0, 0), tail = new Node(0, 0); // sentinels

    public LRUCache(int capacity) {
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node n = map.get(key);
        if (n == null) return -1;
        unlink(n);
        addFront(n);
        return n.val;
    }

    public void put(int key, int value) {
        Node n = map.get(key);
        if (n != null) {
            n.val = value;
            unlink(n);
            addFront(n);
            return;
        }
        if (map.size() == capacity) {
            Node lru = tail.prev;
            unlink(lru);
            map.remove(lru.key);
        }
        n = new Node(key, value);
        map.put(key, n);
        addFront(n);
    }

    private void unlink(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }
    private void addFront(Node n) {
        n.next = head.next;
        n.prev = head;
        head.next.prev = n;
        head.next = n;
    }
}

import java.util.*;
import java.util.concurrent.*;

class RateLimiter {
    private final int maxRequests;
    private final long windowMillis;
    private final Map<String, Deque<Long>> log = new ConcurrentHashMap<>();

    public RateLimiter(int maxRequests, long windowMillis) {
        this.maxRequests = maxRequests;
        this.windowMillis = windowMillis;
    }

    public boolean allow(String clientId, long now) {
        Deque<Long> q = log.computeIfAbsent(clientId, k -> new ArrayDeque<>());
        synchronized (q) {                                  // per-client lock
            while (!q.isEmpty() && q.peekFirst() <= now - windowMillis) {
                q.pollFirst();                              // expire old requests
            }
            if (q.size() < maxRequests) {
                q.addLast(now);
                return true;
            }
            return false;
        }
    }
}

import java.util.*;

class SnapshotArray {
    private final TreeMap<Integer, Integer>[] history;
    private int snapId = 0;

    @SuppressWarnings("unchecked")
    public SnapshotArray(int length) {
        history = new TreeMap[length];
        for (int i = 0; i < length; i++) {
            history[i] = new TreeMap<>();
            history[i].put(0, 0);
        }
    }

    public void set(int index, int val) {
        history[index].put(snapId, val);      // overwrite within current snap
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snapId) {
        return history[index].floorEntry(snapId).getValue();
    }
}

import java.util.*;

class FileCollectionStats {
    private long total = 0;
    private final Map<String, Long> collectionSize = new HashMap<>();

    public void addFile(String name, long size, List<String> collections) {
        total += size;
        if (collections == null) return;
        for (String c : new HashSet<>(collections)) {          // ignore duplicates
            collectionSize.merge(c, size, Long::sum);
        }
    }

    public long totalSize() {
        return total;
    }

    public List<String> topK(int k) {
        PriorityQueue<Map.Entry<String, Long>> heap = new PriorityQueue<>(
            (a, b) -> !a.getValue().equals(b.getValue())
                      ? Long.compare(a.getValue(), b.getValue())
                      : b.getKey().compareTo(a.getKey()));     // min-heap
        for (Map.Entry<String, Long> e : collectionSize.entrySet()) {
            heap.offer(e);
            if (heap.size() > k) heap.poll();
        }
        List<String> result = new ArrayList<>();
        while (!heap.isEmpty()) result.add(heap.poll().getKey());
        Collections.reverse(result);
        return result;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE, best = 0;
        for (int p : prices) {
            if (p < minPrice) minPrice = p;
            else best = Math.max(best, p - minPrice);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int numIslands(char[][] grid) {
        int m = grid.length, n = grid[0].length, islands = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '1') continue;
                islands++;
                Deque<int[]> stack = new ArrayDeque<>();     // iterative DFS
                stack.push(new int[]{i, j});
                grid[i][j] = '0';
                while (!stack.isEmpty()) {
                    int[] c = stack.pop();
                    for (int[] d : dirs) {
                        int r = c[0] + d[0], col = c[1] + d[1];
                        if (r >= 0 && r < m && col >= 0 && col < n && grid[r][col] == '1') {
                            grid[r][col] = '0';
                            stack.push(new int[]{r, col});
                        }
                    }
                }
            }
        }
        return islands;
    }
}

import java.util.*;

class Solution {
    public int findKthLargest(int[] nums, int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>(k + 1);
        for (int x : nums) {
            minHeap.offer(x);
            if (minHeap.size() > k) minHeap.poll();   // drop smallest
        }
        return minHeap.peek();
    }
}

